package com.clogcompanion;

import com.clogcompanion.engine.EstimateMode;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(ClogCompanionConfig.GROUP)
public interface ClogCompanionConfig extends Config
{
	String GROUP = "clog-companion";

	@ConfigItem(
		keyName = "estimateMode",
		name = "Estimate",
		description = "Expected: average attempts (1 / rate). Likely: attempts by which half of players have the drop.",
		position = 0
	)
	default EstimateMode estimateMode()
	{
		return EstimateMode.EXPECTED;
	}

	@ConfigItem(
		keyName = "easyMaxMinutes",
		name = "Easy up to",
		description = "Slots estimated at or under this many minutes are Easy",
		position = 1
	)
	@Range(min = 1)
	@Units(Units.MINUTES)
	default int easyMaxMinutes()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "mediumMaxMinutes",
		name = "Medium up to",
		description = "Slots estimated at or under this many minutes are Medium",
		position = 2
	)
	@Range(min = 1)
	@Units(Units.MINUTES)
	default int mediumMaxMinutes()
	{
		return 300;
	}

	@ConfigItem(
		keyName = "longMaxMinutes",
		name = "Long up to",
		description = "Slots estimated at or under this many minutes are Long; anything above is a Grind",
		position = 3
	)
	@Range(min = 1)
	@Units(Units.MINUTES)
	default int longMaxMinutes()
	{
		return 1500;
	}

	@ConfigItem(keyName = "hideObtained", name = "", description = "", hidden = true)
	default boolean hideObtained()
	{
		return true;
	}

	@ConfigItem(keyName = "onlyMeetsRequirements", name = "", description = "", hidden = true)
	default boolean onlyMeetsRequirements()
	{
		return false;
	}
}

package com.clogcompanion;

import com.clogcompanion.account.AccountStateReader;
import com.clogcompanion.account.ObtainedTracker;
import com.clogcompanion.account.TrackedList;
import com.clogcompanion.data.ClogDataset;
import com.clogcompanion.data.Diaries;
import com.clogcompanion.engine.ClogFilter;
import com.clogcompanion.engine.DifficultyEngine;
import com.clogcompanion.engine.RatedSlot;
import com.clogcompanion.engine.SlotRater;
import com.clogcompanion.model.AccountState;
import com.clogcompanion.ui.ClogPanel;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Clog Companion",
	description = "Ranks Collection Log slots by how quick they are to get",
	tags = {"collection log", "clog", "completionist", "drop rate"}
)
public class ClogCompanionPlugin extends Plugin
{
	/** Clientscript the game runs once per owned item while populating the collection log interface. */
	private static final int COLLECTION_ITEM_SCRIPT = 4100;
	/** Pinned target, stored per RuneScape profile like the owned set. */
	private static final String PINNED_KEY = "pinnedSlot";
	/** Config keys that change ratings; other keys in the group are UI state or our own persistence. */
	private static final Set<String> RATING_KEYS = new HashSet<>(Arrays.asList(
		"estimateMode", "easyMaxMinutes", "mediumMaxMinutes", "longMaxMinutes"));

	@Inject
	private ClogCompanionConfig config;
	@Inject
	private ConfigManager configManager;
	@Inject
	private Gson gson;
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private ItemManager itemManager;

	@Getter
	private ClogDataset dataset;
	private ObtainedTracker obtained;
	private TrackedList tracked;
	private ClogFilter filter;
	private ClogPanel panel;
	private NavigationButton navButton;
	private boolean accountDirty;

	@Override
	protected void startUp()
	{
		dataset = ClogDataset.load(gson);
		log.debug("Clog Companion loaded {} slots across {} entries", dataset.getItems().size(), dataset.getSources().size());
		obtained = new ObtainedTracker(dataset, configManager, gson);
		tracked = new TrackedList(configManager, gson);
		filter = new ClogFilter();
		filter.setHideObtained(config.hideObtained());
		filter.setOnlyMeetsRequirements(config.onlyMeetsRequirements());
		panel = new ClogPanel(itemManager, filter, tracked, this::persistFilter, this::pin, () -> pin(null));
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Clog Companion")
			.icon(ImageUtil.resizeImage(icon, 16, 16))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			obtained.load();
			tracked.load();
		}
		refresh();
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel.closeRoll();
		panel = null;
		filter = null;
		obtained = null;
		tracked = null;
		dataset = null;
	}

	/** Owned items are per account: (re)load when RuneLite resolves the profile, clear when it goes away. */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		boolean gone = event.getNewProfile() == null;
		if (gone)
		{
			obtained.clear();
		}
		else
		{
			obtained.load();
		}
		// The tracked list is EDT-owned (row buttons mutate it); queue before refresh() queues its own EDT work.
		SwingUtilities.invokeLater(() -> trackedProfile(gone));
		refresh();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			obtained.clear();
			SwingUtilities.invokeLater(() -> trackedProfile(true));
			refresh();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ClogCompanionConfig.GROUP.equals(event.getGroup()) && RATING_KEYS.contains(event.getKey()))
		{
			refresh();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_ITEM_SCRIPT || event.getScriptEvent() == null)
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args != null && args.length > 1 && args[1] instanceof Integer)
		{
			int itemId = (Integer) args[1];
			if (itemId > 0)
			{
				obtained.markItemId(itemId);
				obtained.markItemName(itemManager.getItemComposition(itemId).getName());
			}
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		accountDirty = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (Diaries.BY_NAME.containsValue(event.getVarbitId()))
		{
			accountDirty = true;
		}
	}

	/** Script bursts and stat storms both settle here: persist and re-rate at most once per tick. */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		boolean synced = obtained.flush();
		if (synced || accountDirty)
		{
			accountDirty = false;
			refresh();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE && obtained.onChatMessage(Text.removeTags(event.getMessage())))
		{
			refresh();
		}
	}

	public DifficultyEngine engine()
	{
		int easy = config.easyMaxMinutes();
		int medium = Math.max(easy, config.mediumMaxMinutes());
		int longMax = Math.max(medium, config.longMaxMinutes());
		return new DifficultyEngine(config.estimateMode(), easy, medium, longMax);
	}

	/** Re-rates every slot against the current account on the client thread, then updates the panel. */
	private void refresh()
	{
		clientThread.invokeLater(() ->
		{
			ClogDataset data = dataset;
			ObtainedTracker owned = obtained;
			if (data == null || owned == null)
			{
				return;
			}
			boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
			AccountState state = loggedIn ? AccountStateReader.read(client) : AccountState.empty();
			List<RatedSlot> rated = new SlotRater(data, engine()).rateAll(state, owned.obtainedSlotIds());
			String status = !loggedIn ? "Log in to check requirements"
				: owned.isSynced() ? "Synced with this account's log" : "Open your Collection Log once to sync";
			String pinnedId = configManager.getRSProfileConfiguration(ClogCompanionConfig.GROUP, PINNED_KEY);
			RatedSlot pinnedSlot = rated.stream().filter(r -> r.getItem().getId().equals(pinnedId)).findFirst().orElse(null);
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.setStatus(status);
					panel.setPinned(pinnedSlot);
					panel.setSlots(rated);
				}
			});
		});
	}

	private void trackedProfile(boolean gone)
	{
		TrackedList list = tracked;
		if (list == null)
		{
			return;
		}
		if (gone)
		{
			list.clear();
		}
		else
		{
			list.load();
		}
	}

	private void pin(RatedSlot slot)
	{
		if (slot == null)
		{
			configManager.unsetRSProfileConfiguration(ClogCompanionConfig.GROUP, PINNED_KEY);
		}
		else
		{
			tracked.add(slot.getItem().getId());
			configManager.setRSProfileConfiguration(ClogCompanionConfig.GROUP, PINNED_KEY, slot.getItem().getId());
		}
		refresh();
	}

	private void persistFilter()
	{
		configManager.setConfiguration(ClogCompanionConfig.GROUP, "hideObtained", filter.isHideObtained());
		configManager.setConfiguration(ClogCompanionConfig.GROUP, "onlyMeetsRequirements", filter.isOnlyMeetsRequirements());
	}

	@Provides
	ClogCompanionConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClogCompanionConfig.class);
	}
}

package com.clogcompanion.account;

import com.clogcompanion.data.Diaries;
import com.clogcompanion.model.AccountState;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/** Snapshots the logged-in account. Must run on the client thread. */
public final class AccountStateReader
{
	private AccountStateReader()
	{
	}

	public static AccountState read(Client client)
	{
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			levels.put(skill.name(), client.getRealSkillLevel(skill));
		}
		Set<String> quests = new HashSet<>();
		for (Quest quest : Quest.values())
		{
			if (quest.getState(client) == QuestState.FINISHED)
			{
				quests.add(quest.name());
			}
		}
		Set<String> diaries = new HashSet<>();
		for (Map.Entry<String, Integer> e : Diaries.BY_NAME.entrySet())
		{
			if (client.getVarbitValue(e.getValue()) == 1)
			{
				diaries.add(e.getKey());
			}
		}
		return new AccountState(levels, quests, diaries);
	}
}

package com.clogcompanion.account;

import com.clogcompanion.data.ClogDataset;
import com.clogcompanion.model.ClogItem;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Which slots the current account owns, fed by the game's collection log population script
 * (one call per owned item when the log is opened) and the "New item added" chat line,
 * persisted per RuneScape profile.
 */
@Slf4j
public class ObtainedTracker
{
	static final String GROUP = "clog-companion";
	static final String KEY = "obtainedItemIds";
	private static final Pattern NEW_ITEM = Pattern.compile("New item added to your collection log: (.+)");

	private final ClogDataset dataset;
	private final ConfigManager configManager;
	private final Gson gson;
	private final Set<Integer> itemIds = new HashSet<>();
	private boolean synced;
	private boolean dirty;

	public ObtainedTracker(ClogDataset dataset, ConfigManager configManager, Gson gson)
	{
		this.dataset = dataset;
		this.configManager = configManager;
		this.gson = gson;
	}

	/** True once the whole log has been read at least once for this profile. */
	public boolean isSynced()
	{
		return synced;
	}

	public Set<String> obtainedSlotIds()
	{
		return dataset.getItems().stream().filter(i -> itemIds.contains(i.getItemId())).map(ClogItem::getId).collect(Collectors.toSet());
	}

	/** From the game's collection log population script; call {@link #flush()} once the burst ends. */
	public boolean markItemId(int id)
	{
		synced = true;
		dirty |= itemIds.add(id);
		return dirty;
	}

	/** Marks every slot sharing an item name (item ids reported by the game can be variants of the wiki's). */
	public void markItemName(String name)
	{
		for (ClogItem item : dataset.byName(name))
		{
			synced = true;
			dirty |= itemIds.add(item.getItemId());
		}
	}

	/** Persists pending marks; returns true if anything was written. */
	public boolean flush()
	{
		if (!dirty)
		{
			return false;
		}
		dirty = false;
		save();
		return true;
	}

	/** Handles the "New item added to your collection log: X" game message; returns true if it matched. */
	public boolean onChatMessage(String message)
	{
		Matcher m = NEW_ITEM.matcher(message);
		if (!m.find())
		{
			return false;
		}
		boolean changed = false;
		for (ClogItem item : dataset.byName(m.group(1).trim()))
		{
			changed |= itemIds.add(item.getItemId());
		}
		if (changed)
		{
			save();
		}
		return changed;
	}

	public void load()
	{
		itemIds.clear();
		Set<Integer> saved = configManager.getRSProfileConfiguration(GROUP, KEY, new TypeToken<Set<Integer>>()
		{
		}.getType());
		if (saved != null)
		{
			itemIds.addAll(saved);
		}
		synced = !itemIds.isEmpty();
		log.debug("Loaded {} obtained item ids", itemIds.size());
	}

	public void clear()
	{
		itemIds.clear();
		synced = false;
	}

	private void save()
	{
		configManager.setRSProfileConfiguration(GROUP, KEY, gson.toJson(itemIds));
	}

	Set<Integer> itemIds()
	{
		return Collections.unmodifiableSet(itemIds);
	}
}

package com.clogcompanion.account;

import com.clogcompanion.ClogCompanionConfig;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;
import net.runelite.client.config.ConfigManager;

/** Slots the player has chosen to go for, persisted per RuneScape profile. */
public class TrackedList
{
	static final String KEY = "trackedSlots";

	private final ConfigManager configManager;
	private final Gson gson;
	private final Set<String> slotIds = new LinkedHashSet<>();

	public TrackedList(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public boolean contains(String slotId)
	{
		return slotIds.contains(slotId);
	}

	public Set<String> ids()
	{
		return Collections.unmodifiableSet(slotIds);
	}

	public int size()
	{
		return slotIds.size();
	}

	/** Adds if absent, removes if present; returns true when the slot is now tracked. */
	public boolean toggle(String slotId)
	{
		boolean tracked = slotIds.add(slotId);
		if (!tracked)
		{
			slotIds.remove(slotId);
		}
		save();
		return tracked;
	}

	public void add(String slotId)
	{
		if (slotIds.add(slotId))
		{
			save();
		}
	}

	/** Drops every tracked slot the player now owns; returns how many were removed. */
	public int clearCompleted(Set<String> obtainedSlotIds)
	{
		int before = slotIds.size();
		if (slotIds.removeAll(obtainedSlotIds))
		{
			save();
		}
		return before - slotIds.size();
	}

	public void load()
	{
		slotIds.clear();
		Set<String> saved = configManager.getRSProfileConfiguration(ClogCompanionConfig.GROUP, KEY, new TypeToken<Set<String>>()
		{
		}.getType());
		if (saved != null)
		{
			slotIds.addAll(saved);
		}
	}

	public void clear()
	{
		slotIds.clear();
	}

	private void save()
	{
		configManager.setRSProfileConfiguration(ClogCompanionConfig.GROUP, KEY, gson.toJson(slotIds));
	}
}

package com.clogcompanion.data;

import com.clogcompanion.model.ClogItem;
import com.clogcompanion.model.ClogSource;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import lombok.Getter;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/** The bundled collection log: every slot joined to its curated source. */
public class ClogDataset
{
	private static class ItemsFile
	{
		List<ClogItem> items;
	}

	@Getter
	private final List<ClogItem> items;
	@Getter
	private final Map<String, ClogSource> sources;
	private final Map<String, ClogItem> byId = new HashMap<>();
	private final Map<String, List<ClogItem>> byName = new HashMap<>();

	ClogDataset(List<ClogItem> items, List<ClogSource> sourceList)
	{
		this.items = Collections.unmodifiableList(new ArrayList<>(items));
		Map<String, ClogSource> map = new LinkedHashMap<>();
		for (ClogSource s : sourceList)
		{
			map.put(s.getId(), s);
		}
		this.sources = Collections.unmodifiableMap(map);
		for (ClogItem item : items)
		{
			byId.put(item.getId(), item);
			byName.computeIfAbsent(item.getName().toLowerCase(Locale.ROOT), k -> new ArrayList<>()).add(item);
		}
	}

	public static ClogDataset load(Gson gson)
	{
		try (Reader items = open("clog-items.json"); Reader sources = open("clog-sources.json"))
		{
			ItemsFile file = gson.fromJson(items, ItemsFile.class);
			List<ClogSource> list = gson.fromJson(sources, new TypeToken<List<ClogSource>>()
			{
			}.getType());
			return new ClogDataset(file.items, list);
		}
		catch (IOException | RuntimeException e)
		{
			throw new IllegalStateException("Clog Companion data failed to load", e);
		}
	}

	private static Reader open(String name) throws IOException
	{
		InputStream in = ClogDataset.class.getResourceAsStream("/com/clogcompanion/" + name);
		if (in == null)
		{
			throw new IOException("missing resource " + name);
		}
		return new InputStreamReader(in, StandardCharsets.UTF_8);
	}

	/** The entry the slot is listed under. */
	public ClogSource sourceOf(ClogItem item)
	{
		return sources.get(item.getSourceId());
	}

	/** The source whose per-attempt time applies to the slot (differs from {@link #sourceOf} for catch-all entries). */
	public ClogSource timeSourceOf(ClogItem item)
	{
		String id = item.getTimeSourceId();
		return id == null ? sourceOf(item) : sources.getOrDefault(id, sourceOf(item));
	}

	public Optional<ClogItem> byId(String id)
	{
		return Optional.ofNullable(byId.get(id));
	}

	/** Every slot sharing an item name; the game marks all of them when one is obtained. */
	public List<ClogItem> byName(String itemName)
	{
		return byName.getOrDefault(itemName.toLowerCase(Locale.ROOT), Collections.emptyList());
	}

	/** Dangling references and unknown constant names; empty when the data is consistent. */
	public List<String> validate()
	{
		List<String> problems = new ArrayList<>();
		for (ClogItem item : items)
		{
			if (byId.get(item.getId()) != item)
			{
				problems.add(item.getId() + ": duplicate id");
			}
			if (!sources.containsKey(item.getSourceId()))
			{
				problems.add(item.getId() + ": unknown sourceId " + item.getSourceId());
			}
			if (item.getTimeSourceId() != null && !sources.containsKey(item.getTimeSourceId()))
			{
				problems.add(item.getId() + ": unknown timeSourceId " + item.getTimeSourceId());
			}
		}
		for (ClogSource s : sources.values())
		{
			if (s.getCategory() == null)
			{
				problems.add(s.getId() + ": unknown category");
			}
			for (String skill : s.getRequirements().getSkills().keySet())
			{
				if (!isEnum(Skill.class, skill))
				{
					problems.add(s.getId() + ": unknown skill " + skill);
				}
			}
			for (String quest : s.getRequirements().getQuests())
			{
				if (!isEnum(Quest.class, quest))
				{
					problems.add(s.getId() + ": unknown quest " + quest);
				}
			}
			for (String diary : s.getRequirements().getDiaries())
			{
				if (!Diaries.BY_NAME.containsKey(diary))
				{
					problems.add(s.getId() + ": unknown diary " + diary);
				}
			}
		}
		return problems;
	}

	private static <E extends Enum<E>> boolean isEnum(Class<E> type, String name)
	{
		try
		{
			Enum.valueOf(type, name);
			return true;
		}
		catch (IllegalArgumentException e)
		{
			return false;
		}
	}
}

package com.clogcompanion.data;

