package com.clogcompanion.engine;

import com.clogcompanion.model.Category;
import com.clogcompanion.model.Tier;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;
import lombok.Getter;
import lombok.Setter;

/** Mutable filter criteria; the panel binds its controls to one instance. */
@Getter
@Setter
public class ClogFilter
{
	private Set<Tier> tiers = EnumSet.range(Tier.EASY, Tier.GRIND);
	private Category category;
	private boolean hideObtained = true;
	private boolean onlyMeetsRequirements;
	private String search = "";

	public boolean test(RatedSlot s)
	{
		if (hideObtained && s.isObtained())
		{
			return false;
		}
		if (!tiers.contains(s.getTier()))
		{
			return false;
		}
		if (category != null && s.getSource().getCategory() != category)
		{
			return false;
		}
		if (onlyMeetsRequirements && !s.getUnmet().isEmpty())
		{
			return false;
		}
		String q = search == null ? "" : search.trim().toLowerCase(Locale.ROOT);
		return q.isEmpty()
			|| s.getItem().getName().toLowerCase(Locale.ROOT).contains(q)
			|| s.getSource().getName().toLowerCase(Locale.ROOT).contains(q);
	}
}

package com.clogcompanion.engine;

import java.util.Comparator;

public enum ClogSorter implements Comparator<RatedSlot>
{
	EASIEST("Easiest first")
	{
		@Override
		public int compare(RatedSlot a, RatedSlot b)
		{
			int byTier = Integer.compare(a.getTier().ordinal(), b.getTier().ordinal());
			return byTier != 0 ? byTier : FASTEST.compare(a, b);
		}
	},
	FASTEST("Fastest first")
	{
		@Override
		public int compare(RatedSlot a, RatedSlot b)
		{
			return Double.compare(a.getMinutes().orElse(Double.MAX_VALUE), b.getMinutes().orElse(Double.MAX_VALUE));
		}
	},
	RAREST("Rarest first")
	{
		@Override
		public int compare(RatedSlot a, RatedSlot b)
		{
			return Double.compare(rate(a), rate(b));
		}
	},
	NAME("A-Z")
	{
		@Override
		public int compare(RatedSlot a, RatedSlot b)
		{
			return String.CASE_INSENSITIVE_ORDER.compare(a.getItem().getName(), b.getItem().getName());
		}
	};

	private final String label;

	ClogSorter(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}

	private static double rate(RatedSlot s)
	{
		Double r = s.getItem().getRate();
		return r == null ? Double.MAX_VALUE : r;
	}
}

package com.clogcompanion.engine;

import com.clogcompanion.model.ClogItem;
import com.clogcompanion.model.ClogSource;
import com.clogcompanion.model.Tier;
import java.util.OptionalDouble;

/** Turns a slot's drop rate and its source's per-attempt cost into minutes and a tier. */
public class DifficultyEngine
{
	private static final double LIKELY_PROBABILITY = 0.5;

	private final EstimateMode mode;
	private final int easyMax;
	private final int mediumMax;
	private final int longMax;

	public DifficultyEngine(EstimateMode mode, int easyMax, int mediumMax, int longMax)
	{
		this.mode = mode;
		this.easyMax = easyMax;
		this.mediumMax = mediumMax;
		this.longMax = longMax;
	}

	public OptionalDouble expectedMinutes(ClogItem item, ClogSource source)
	{
		Double rate = item.getRate();
		if (rate == null || rate <= 0 || source == null || !source.isRated())
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of(source.getSetupMinutes() + attempts(rate) * source.getMinutesPerAttempt());
	}

	/** The item's own challenge when set, else its source's. */
	public static int challenge(ClogItem item, ClogSource source)
	{
		Integer own = item.getChallenge();
		return own != null ? Math.max(1, Math.min(5, own)) : source == null ? 1 : source.getChallenge();
	}

	/** Combined rating: the time tier, raised to a floor set by the challenge (3 = Medium, 4 = Long, 5 = Grind). */
	public Tier tier(ClogItem item, ClogSource source)
	{
		Tier byTime = timeTier(item, source);
		if (byTime == Tier.UNRATED)
		{
			return byTime;
		}
		Tier floor = challengeFloor(challenge(item, source));
		return floor.ordinal() > byTime.ordinal() ? floor : byTime;
	}

	static Tier challengeFloor(int challenge)
	{
		switch (challenge)
		{
			case 5:
				return Tier.GRIND;
			case 4:
				return Tier.LONG;
			case 3:
				return Tier.MEDIUM;
			default:
				return Tier.EASY;
		}
	}

	private Tier timeTier(ClogItem item, ClogSource source)
	{
		OptionalDouble minutes = expectedMinutes(item, source);
		if (!minutes.isPresent())
		{
			return Tier.UNRATED;
		}
		double m = minutes.getAsDouble();
		if (m <= easyMax)
		{
			return Tier.EASY;
		}
		if (m <= mediumMax)
		{
			return Tier.MEDIUM;
		}
		if (m <= longMax)
		{
			return Tier.LONG;
		}
		return Tier.GRIND;
	}

	private double attempts(double rate)
	{
		if (rate >= 1.0)
		{
			return 1;
		}
		if (mode == EstimateMode.LIKELY)
		{
			return Math.max(1, Math.log(1 - LIKELY_PROBABILITY) / Math.log1p(-rate));
		}
		return 1 / rate;
	}

	public static String formatMinutes(OptionalDouble minutes)
	{
		return minutes.isPresent() ? formatMinutes(minutes.getAsDouble()) : "?";
	}

	public static String formatMinutes(double minutes)
	{
		long total = Math.round(minutes);
		long days = total / 1440;
		long hours = (total % 1440) / 60;
		long mins = total % 60;
		if (days > 0)
		{
			return days + "d " + hours + "h";
		}
		if (hours > 0)
		{
			return hours + "h " + mins + "m";
		}
		return mins + "m";
	}
}

package com.clogcompanion.engine;

public enum EstimateMode
{
	/** Mean attempts: 1 / rate. */
	EXPECTED("Expected (average)"),
	/** Median attempts: the number by which half of players have the drop. */
	LIKELY("Likely (median)");

	private final String label;

	EstimateMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

