package com.clogcompanion.data;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.clogcompanion.model.ClogItem;
import com.clogcompanion.model.ClogSource;
import com.google.gson.Gson;
import java.util.List;
import org.junit.Test;

/** Integrity of the bundled data. Runs against the real resources. */
public class ClogDatasetTest
{
	private static final ClogDataset DATA = ClogDataset.load(new Gson());

	@Test
	public void loadsAFullLog()
	{
		assertTrue("expected >1000 slots, got " + DATA.getItems().size(), DATA.getItems().size() > 1000);
		assertTrue(DATA.getSources().size() >= 100);
	}

	@Test
	public void everyReferenceResolves()
	{
		List<String> problems = DATA.validate();
		assertTrue(String.join("\n", problems), problems.isEmpty());
	}

	@Test
	public void everyItemHasAnId()
	{
		long missing = DATA.getItems().stream().filter(i -> i.getItemId() <= 0).count();
		assertTrue("slots without an item id: " + missing, missing <= 5);
	}

	@Test
	public void reportsUnratedCoverage()
	{
		long unrated = DATA.getItems().stream()
			.filter(i -> i.getRate() == null || !DATA.timeSourceOf(i).isRated()).count();
		System.out.println("UNRATED slots: " + unrated + " / " + DATA.getItems().size());
		assertTrue("more than half the log is unrated", unrated * 2 < DATA.getItems().size());
	}

	@Test
	public void lookupsWork()
	{
		ClogItem whip = DATA.byId("abyssal_sire:abyssal_whip").orElseThrow(AssertionError::new);
		assertEquals("Abyssal Sire", DATA.sourceOf(whip).getName());
		assertTrue(DATA.byName("Dragon pickaxe").size() > 1);
	}

	@Test
	public void catchAllEntriesBorrowTheRealSourcesTime()
	{
		ClogItem pet = DATA.byId("all_pets:baby_mole").orElseThrow(AssertionError::new);
		ClogSource time = DATA.timeSourceOf(pet);
		assertEquals("giant_mole", time.getId());
		assertTrue(time.isRated());
	}
}

package com.clogcompanion.data;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.clogcompanion.model.Category;
import com.clogcompanion.model.ClogItem;
import com.clogcompanion.model.ClogSource;
import com.clogcompanion.model.Requirements;
import com.google.common.collect.ImmutableMap;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/** Proves {@link ClogDataset#validate()} actually catches each class of data defect. */
public class ClogDatasetValidateTest
{
	private static ClogSource source(String id, Category cat, Requirements req)
	{
		return new ClogSource(id, id, cat, 1.0, 0.0, req, null, null);
	}

	private static ClogItem item(String id, String sourceId, String timeSourceId)
	{
		return new ClogItem(id, sourceId, timeSourceId, 1, id, 0.5, "1/2", null, null);
	}

	@Test
	public void cleanDataHasNoProblems()
	{
		ClogDataset d = new ClogDataset(Collections.singletonList(item("a:x", "a", null)),
			Collections.singletonList(source("a", Category.BOSSES, Requirements.none())));
		assertTrue(d.validate().isEmpty());
	}

	@Test
	public void reportsEveryDefect()
	{
		Requirements bad = new Requirements(ImmutableMap.of("SLAYING", 1), Collections.singletonList("NOT_A_QUEST"),
			Collections.singletonList("DIARY_NOWHERE_EASY"));
		ClogDataset d = new ClogDataset(
			Arrays.asList(item("a:x", "a", null), item("a:x", "a", null), item("a:y", "missing", "gone")),
			Arrays.asList(source("a", null, bad)));
		List<String> problems = d.validate();
		assertEquals(String.join("\n", problems), 7, problems.size());
		assertTrue(problems.contains("a:x: duplicate id"));
		assertTrue(problems.contains("a:y: unknown sourceId missing"));
		assertTrue(problems.contains("a:y: unknown timeSourceId gone"));
		assertTrue(problems.contains("a: unknown category"));
		assertTrue(problems.contains("a: unknown skill SLAYING"));
		assertTrue(problems.contains("a: unknown quest NOT_A_QUEST"));
		assertTrue(problems.contains("a: unknown diary DIARY_NOWHERE_EASY"));
	}
}

package com.clogcompanion.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.clogcompanion.model.Category;
import com.clogcompanion.model.ClogItem;
import com.clogcompanion.model.ClogSource;
import com.clogcompanion.model.Requirements;
import com.clogcompanion.model.Tier;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.OptionalDouble;
import java.util.stream.Collectors;
import org.junit.Test;

public class ClogFilterTest
{
	private static RatedSlot slot(String name, Category cat, Tier tier, double minutes, boolean obtained, List<String> unmet)
	{
		ClogSource src = new ClogSource("s", "Src", cat, 1.0, 0.0, Requirements.none(), null, null);
		ClogItem it = new ClogItem("s:" + name, "s", null, 1, name, 0.5, "1/2", null, null);
		return new RatedSlot(it, src, tier, 1, OptionalDouble.of(minutes), unmet, obtained);
	}

	private static final RatedSlot EASY_BOSS = slot("Whip", Category.BOSSES, Tier.EASY, 10, false, Collections.emptyList());
	private static final RatedSlot GRIND_CLUE = slot("3rd age", Category.CLUES, Tier.GRIND, 9999, false, Collections.emptyList());
	private static final RatedSlot OWNED = slot("Pet", Category.BOSSES, Tier.EASY, 10, true, Collections.emptyList());
	private static final RatedSlot LOCKED = slot("Fang", Category.RAIDS, Tier.MEDIUM, 100, false, Collections.singletonList("Slayer 93 (have 1)"));
	private static final List<RatedSlot> ALL = Arrays.asList(EASY_BOSS, GRIND_CLUE, OWNED, LOCKED);

	private static List<String> names(ClogFilter f)
	{
		return ALL.stream().filter(f::test).map(s -> s.getItem().getName()).collect(Collectors.toList());
	}

	@Test
	public void defaultFilterHidesObtainedOnly()
	{
		assertEquals(Arrays.asList("Whip", "3rd age", "Fang"), names(new ClogFilter()));
	}

	@Test
	public void tierAndCategory()
	{
		ClogFilter f = new ClogFilter();
		f.setTiers(EnumSet.of(Tier.EASY));
		f.setHideObtained(false);
		assertEquals(Arrays.asList("Whip", "Pet"), names(f));
		f.setCategory(Category.CLUES);
		assertTrue(names(f).isEmpty());
	}

	@Test
	public void requirementsAndSearch()
	{
		ClogFilter f = new ClogFilter();
		f.setOnlyMeetsRequirements(true);
		assertEquals(Arrays.asList("Whip", "3rd age"), names(f));
		f.setSearch("AGE");
		assertEquals(Collections.singletonList("3rd age"), names(f));
	}

	@Test
	public void nullSearchMeansNoFilter()
	{
		ClogFilter f = new ClogFilter();
		f.setSearch(null);
		assertEquals(3, names(f).size());
	}

	@Test
	public void searchMatchesSourceNameToo()
	{
		ClogFilter f = new ClogFilter();
		f.setSearch("  src ");
		assertEquals(3, names(f).size());
	}
}

package com.clogcompanion.engine;

import static org.junit.Assert.assertEquals;
import com.clogcompanion.model.Category;
import com.clogcompanion.model.ClogItem;
import com.clogcompanion.model.ClogSource;
import com.clogcompanion.model.Requirements;
import com.clogcompanion.model.Tier;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.OptionalDouble;
import java.util.stream.Collectors;
import org.junit.Test;

public class ClogSorterTest
{
	private static RatedSlot slot(String name, Double rate, OptionalDouble minutes)
	{
		ClogSource src = new ClogSource("s", "Src", Category.BOSSES, 1.0, 0.0, Requirements.none(), null, null);
		ClogItem it = new ClogItem("s:" + name, "s", null, 1, name, rate, "", null, null);
		return new RatedSlot(it, src, minutes.isPresent() ? Tier.EASY : Tier.UNRATED, 1, minutes, Collections.emptyList(), false);
	}

	private static final RatedSlot B = slot("B", 0.5, OptionalDouble.of(20));
	private static final RatedSlot A = slot("a", 0.1, OptionalDouble.of(5));
	private static final RatedSlot C = slot("c", null, OptionalDouble.empty());

	private static List<String> order(ClogSorter s)
	{
		return Arrays.asList(C, B, A).stream().sorted(s).map(r -> r.getItem().getName()).collect(Collectors.toList());
	}

	@Test
	public void fastestPutsUnratedLast()
	{
		assertEquals(Arrays.asList("a", "B", "c"), order(ClogSorter.FASTEST));
	}

	@Test
	public void rarestIsAscendingRateUnknownLast()
	{
		assertEquals(Arrays.asList("a", "B", "c"), order(ClogSorter.RAREST));
	}

	@Test
	public void easiestOrdersByTierThenTime()
	{
		RatedSlot hardButQuick = slot("d", 0.9, OptionalDouble.of(1));
		hardButQuick = new RatedSlot(hardButQuick.getItem(), hardButQuick.getSource(), Tier.LONG, 4, OptionalDouble.of(1), Collections.emptyList(), false);
		List<String> order = Arrays.asList(C, hardButQuick, B, A).stream().sorted(ClogSorter.EASIEST)
			.map(r -> r.getItem().getName()).collect(Collectors.toList());
		assertEquals(Arrays.asList("a", "B", "d", "c"), order);
	}

	@Test
	public void nameIsCaseInsensitiveAlphabetical()
	{
		assertEquals(Arrays.asList("a", "B", "c"), order(ClogSorter.NAME));
	}
}

package com.clogcompanion.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import com.clogcompanion.model.Category;
import com.clogcompanion.model.ClogItem;
import com.clogcompanion.model.ClogSource;
import com.clogcompanion.model.Requirements;
import com.clogcompanion.model.Tier;
import org.junit.Test;

public class DifficultyEngineTest
{
	private static final DifficultyEngine EXPECTED = new DifficultyEngine(EstimateMode.EXPECTED, 60, 300, 1500);
	private static final DifficultyEngine LIKELY = new DifficultyEngine(EstimateMode.LIKELY, 60, 300, 1500);

	private static ClogSource source(Double perAttempt, Double setup)
	{
		return new ClogSource("s", "S", Category.BOSSES, perAttempt, setup, Requirements.none(), null, null);
	}

	private static ClogItem item(Double rate)
	{
		return new ClogItem("s:i", "s", null, 1, "I", rate, "1/x", null, null);
	}

	@Test
	public void expectedModeIsOneOverRate()
	{
		assertEquals(2.0 * 512, EXPECTED.expectedMinutes(item(1.0 / 512), source(2.0, 0.0)).getAsDouble(), 1e-6);
	}

	@Test
	public void likelyModeUsesMedianAttempts()
	{
		// ln(0.5) / ln(1 - 1/512) ≈ 354.5 attempts
		assertEquals(354.5, LIKELY.expectedMinutes(item(1.0 / 512), source(1.0, 0.0)).getAsDouble(), 0.5);
	}

	@Test
	public void likelyModeNeverEstimatesUnderOneAttempt()
	{
		// ln(0.5)/ln(0.25) = 0.5 attempts; a drop still costs at least one attempt.
		assertEquals(40.0, LIKELY.expectedMinutes(item(0.75), source(40.0, 0.0)).getAsDouble(), 1e-9);
	}

	@Test
	public void setupIsAddedOnce()
	{
		assertEquals(100 + 10, EXPECTED.expectedMinutes(item(1.0), source(10.0, 100.0)).getAsDouble(), 1e-9);
	}

	@Test
	public void guaranteedDropIsOneAttemptInBothModes()
	{
		assertEquals(5.0, EXPECTED.expectedMinutes(item(1.0), source(5.0, 0.0)).getAsDouble(), 1e-9);
		assertEquals(5.0, LIKELY.expectedMinutes(item(1.0), source(5.0, 0.0)).getAsDouble(), 1e-9);
	}

	@Test
	public void missingRateOrTimeIsUnrated()
	{
		assertFalse(EXPECTED.expectedMinutes(item(null), source(5.0, 0.0)).isPresent());
		assertFalse(EXPECTED.expectedMinutes(item(0.5), source(null, 0.0)).isPresent());
		assertFalse(EXPECTED.expectedMinutes(item(0.5), null).isPresent());
		assertEquals(Tier.UNRATED, EXPECTED.tier(item(null), source(5.0, 0.0)));
	}

	@Test
	public void tierThresholdsAreInclusiveUpperBounds()
	{
		assertEquals(Tier.EASY, EXPECTED.tier(item(1.0), source(60.0, 0.0)));
		assertEquals(Tier.MEDIUM, EXPECTED.tier(item(1.0), source(61.0, 0.0)));
		assertEquals(Tier.MEDIUM, EXPECTED.tier(item(1.0), source(300.0, 0.0)));
		assertEquals(Tier.LONG, EXPECTED.tier(item(1.0), source(301.0, 0.0)));
		assertEquals(Tier.LONG, EXPECTED.tier(item(1.0), source(1500.0, 0.0)));
		assertEquals(Tier.GRIND, EXPECTED.tier(item(1.0), source(1501.0, 0.0)));
	}

	@Test
	public void clueCasketUniqueIsNotEasy()
	{
		// Opening the casket is instant, but each attempt is a whole master clue (~25 min).
		assertEquals(Tier.GRIND, EXPECTED.tier(item(1.0 / 28988), source(25.0, 0.0)));
		assertEquals(Tier.LONG, EXPECTED.tier(item(1.0 / 50), source(25.0, 0.0)));
		assertEquals(Tier.MEDIUM, EXPECTED.tier(item(1.0 / 5), source(25.0, 0.0)));
	}

	@Test
	public void challengeRaisesTheTierFloorButNeverLowersIt()
	{
		ClogSource easyBoss = new ClogSource("s", "S", Category.BOSSES, 1.5, 0.0, Requirements.none(), 4, null);
		assertEquals(Tier.LONG, EXPECTED.tier(item(1.0), easyBoss));
		ClogSource grind = new ClogSource("s", "S", Category.BOSSES, 2000.0, 0.0, Requirements.none(), 2, null);
		assertEquals(Tier.GRIND, EXPECTED.tier(item(1.0), grind));
		ClogItem conditional = new ClogItem("s:i", "s", null, 1, "I", 1.0, "Always", null, 5);
		assertEquals(Tier.GRIND, EXPECTED.tier(conditional, source(3.0, 0.0)));
		assertEquals(5, DifficultyEngine.challenge(conditional, easyBoss));
		assertEquals(Tier.UNRATED, EXPECTED.tier(item(null), easyBoss));
		assertEquals(1, DifficultyEngine.challenge(item(1.0), new ClogSource("s", "S", Category.BOSSES, 1.0, 0.0, null, 0, null)));
		assertEquals(5, DifficultyEngine.challenge(item(1.0), new ClogSource("s", "S", Category.BOSSES, 1.0, 0.0, null, 7, null)));
		assertEquals(1, DifficultyEngine.challenge(item(1.0), null));
	}

	@Test
	public void formatMinutes()
	{
		assertEquals("45m", DifficultyEngine.formatMinutes(45));
		assertEquals("2h 10m", DifficultyEngine.formatMinutes(130));
		assertEquals("3d 4h", DifficultyEngine.formatMinutes(3 * 1440 + 4 * 60 + 12));
		assertEquals("0m", DifficultyEngine.formatMinutes(0.2));
	}
}

